// @generated by packages/emails (`pnpm emails:build`) from its templates and the catalogs
// in packages/emails/messages. Do not edit: build again.

use crate::{
    TemplateKey,
    defaults::{ContextStrings, DefaultTemplate},
};

/// `defaults/<path>.subject.j2`, `.html.j2` and `.txt.j2`.
macro_rules! sources {
    ($path:literal) => {
        DefaultTemplate {
            subject: include_str!(concat!("../../defaults/", $path, ".subject.j2")),
            html: include_str!(concat!("../../defaults/", $path, ".html.j2")),
            text: Some(include_str!(concat!("../../defaults/", $path, ".txt.j2"))),
        }
    };
}

/// The languages the build has defaults in, English first.
pub(crate) const LANGUAGES: &[&str] = &["en", "sr-Latn"];

/// An English default: every key has one.
pub(crate) fn english(key: TemplateKey) -> DefaultTemplate {
    match key {
        TemplateKey::Layout => DefaultTemplate {
            subject: "",
            html: include_str!("../../defaults/layout.html.j2"),
            text: None,
        },
        TemplateKey::OrderConfirmation => sources!("order_confirmation"),
        TemplateKey::OrderShipped => sources!("order_shipped"),
        TemplateKey::OrderTrackingUpdated => sources!("order_tracking_updated"),
        TemplateKey::OrderCancelled => sources!("order_cancelled"),
        TemplateKey::CustomerLoginCode => sources!("customer_login_code"),
        TemplateKey::CustomerErasureRequested => sources!("customer_erasure_requested"),
        TemplateKey::StaffNewOrder => sources!("staff_new_order"),
        TemplateKey::StaffInvite => sources!("staff_invite"),
        TemplateKey::StaffPasswordReset => sources!("staff_password_reset"),
        TemplateKey::SupplierPurchaseOrder => sources!("supplier_purchase_order"),
    }
}

/// The default of `key` in `language` (not English): the buyer's emails have one.
pub(crate) fn translated(language: &str, key: TemplateKey) -> Option<DefaultTemplate> {
    match (language, key) {
        ("sr-Latn", TemplateKey::OrderConfirmation) => Some(sources!("sr-Latn/order_confirmation")),
        ("sr-Latn", TemplateKey::OrderShipped) => Some(sources!("sr-Latn/order_shipped")),
        ("sr-Latn", TemplateKey::OrderTrackingUpdated) => {
            Some(sources!("sr-Latn/order_tracking_updated"))
        }
        ("sr-Latn", TemplateKey::OrderCancelled) => Some(sources!("sr-Latn/order_cancelled")),
        ("sr-Latn", TemplateKey::CustomerLoginCode) => {
            Some(sources!("sr-Latn/customer_login_code"))
        }
        ("sr-Latn", TemplateKey::CustomerErasureRequested) => {
            Some(sources!("sr-Latn/customer_erasure_requested"))
        }
        _ => None,
    }
}

